package com.virtualwardrobe.enquiries;

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;
import com.virtualwardrobe.identity.*;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Store serialization is shared with membership changes. Staff never lock a customer account. */
@Service
public class EnquiryService {
    private static final String CONSENT_VERSION="callback-share-v1-2026-10-27";
    private static final Set<String> STATUSES=Set.of("NEW","OPEN","IN_PROGRESS","AWAITING_CUSTOMER_RESPONSE","CUSTOMER_REPLIED","CLOSED");
    private static final List<String> OUTCOMES=List.of("CONTACTED","CONVERTED","NOT_INTERESTED","UNREACHABLE");
    private static final Map<String,Set<String>> TRANSITIONS=Map.of("OPEN",Set.of("IN_PROGRESS","AWAITING_CUSTOMER_RESPONSE","CLOSED"),"IN_PROGRESS",Set.of("AWAITING_CUSTOMER_RESPONSE","CLOSED"),"AWAITING_CUSTOMER_RESPONSE",Set.of("IN_PROGRESS","CLOSED"),"CUSTOMER_REPLIED",Set.of("IN_PROGRESS","AWAITING_CUSTOMER_RESPONSE","CLOSED"));
    private final JdbcTemplate jdbc;private final IdentityService identity;private final int retentionDays;private final Gson json=new Gson();
    public EnquiryService(JdbcTemplate jdbc,IdentityService identity,@Value("${APP_ENQUIRY_CONTACT_RETENTION_DAYS:180}")int retentionDays){this.jdbc=jdbc;this.identity=identity;this.retentionDays=retentionDays;if(retentionDays<1||retentionDays>3650)throw new IllegalArgumentException("Invalid enquiry contact retention");}
    private String consentVersion(){return CONSENT_VERSION+"-r"+retentionDays;}
    public Map<String,Object> config(){return Map.of("consent",Map.of("version",consentVersion(),"notice","I agree to share my name, unverified mobile number, chosen product and optional note with this store for callback follow-up. App contact details and conversation text remain while the enquiry is active, are removed on account deletion, and are removed within "+retentionDays+" days after closure. Non-identifying operational history remains. My try-on photos are not shared."),"limits",Map.of("noteChars",2000,"messageChars",4000),"outcomes",OUTCOMES);}
    public IdentityService.Account customer(){var a=identity.current();if(!a.kind().equals("CUSTOMER"))throw ApiProblem.missing();return a;}
    private UUID ownerLock(){UUID owner=customer().id();jdbc.queryForObject("SELECT id FROM vw_account WHERE id=? FOR UPDATE",UUID.class,owner);customer();return owner;}
    private String text(Map<String,Object> row,String field){return Objects.toString(row.get(field),"");}
    private UUID id(Map<String,Object> row,String field){return(UUID)row.get(field);}
    private String timestamp(Map<String,Object> row,String field){return row.get(field)==null?null:((Timestamp)row.get(field)).toInstant().toString();}
    private boolean available(Map<String,Object> row){return text(row,"contact_state").equals("AVAILABLE");}
    private Map<String,Object> row(UUID id,UUID store,boolean lock){var values=store==null?jdbc.queryForList("SELECT * FROM vw_enquiry WHERE id=?"+(lock?" FOR UPDATE":""),id):jdbc.queryForList("SELECT * FROM vw_enquiry WHERE id=? AND store_id=?"+(lock?" FOR UPDATE":""),id,store);if(values.isEmpty())throw ApiProblem.missing();return values.getFirst();}
    private IdentityService.Account staff(UUID store,boolean lock){if(lock)identity.lockAdministration();var actor=identity.workforce();if(lock)identity.lockStore(store);identity.requireStore(actor,store,false);return actor;}
    private record Scope(IdentityService.Account actor,Map<String,Object> enquiry) { }
    private Scope lockedStaff(UUID store,UUID enquiry){var actor=staff(store,true);return new Scope(actor,row(enquiry,store,true));}
    private Map<String,Object> lockedCustomer(UUID enquiry){UUID owner=ownerLock();var initial=row(enquiry,null,false);if(!owner.equals(id(initial,"customer_id")))throw ApiProblem.missing();identity.lockAdministration();identity.lockStore(id(initial,"store_id"));var current=row(enquiry,id(initial,"store_id"),true);if(!owner.equals(id(current,"customer_id")))throw ApiProblem.missing();return current;}
    private boolean eligible(UUID user,UUID store){return jdbc.queryForObject("SELECT count(*) FROM vw_membership m JOIN vw_account a ON a.id=m.account_id WHERE m.account_id=? AND m.store_id=? AND m.state='ACTIVE' AND m.accepted_at IS NOT NULL AND m.role IN('STAFF','STORE_ADMIN') AND a.kind='WORKFORCE' AND a.enabled=TRUE",Integer.class,user,store)>0;}
    private void requireEligible(UUID user,UUID store){if(!eligible(user,store))throw new ApiProblem(409,"INVALID_ASSIGNEE","Choose an enabled accepted member of this store");}
    private void requireText(Map<String,Object> row){if(!available(row))throw new ApiProblem(409,"CONTACT_REMOVED","Personal details and conversation text have been removed for this enquiry");}
    private void requireActive(Map<String,Object> row){if(text(row,"status").equals("CLOSED"))throw new ApiProblem(409,"ENQUIRY_CLOSED","This enquiry is closed; submit a new request or ask the store to reopen it");}
    private void event(Map<String,Object> row,UUID actor,String type,String visibility,String body,String fromStatus,String toStatus,UUID fromAssignee,UUID toAssignee,String outcome){jdbc.update("INSERT INTO vw_enquiry_event(enquiry_id,actor_id,event_type,visibility,body,from_status,to_status,from_assignee_id,to_assignee_id,outcome) VALUES(?,?,?,?,?,?,?,?,?,?)",row.get("id"),actor,type,visibility,body,fromStatus,toStatus,fromAssignee,toAssignee,outcome);}
    private void touch(UUID id){jdbc.update("UPDATE vw_enquiry SET updated_at=CURRENT_TIMESTAMP WHERE id=?",id);}
    @Transactional public Map<String,Object> submit(Map<String,Object> body){
        UUID owner=ownerLock();var actor=customer();if(!(body.get("consent") instanceof Map<?,?> consent)||!consentVersion().equals(consent.get("version"))||!Boolean.TRUE.equals(consent.get("shareContact")))throw new ApiProblem(409,"CONTACT_CONSENT_REQUIRED","Confirm the current notice to share contact details with this store");
        UUID product=Inputs.id(Inputs.text(body,"productId",40));String note=Inputs.optional(body,"note",2000);identity.lockAdministration();
        var values=jdbc.queryForList("SELECT p.*,s.name AS store_name,s.status AS store_status FROM vw_product p JOIN vw_store s ON s.id=p.store_id WHERE p.id=?",product);if(values.isEmpty())throw ApiProblem.missing();var p=values.getFirst();UUID store=id(p,"store_id");identity.lockStore(store);
        var existing=jdbc.queryForList("SELECT * FROM vw_enquiry WHERE customer_id=? AND product_id=? AND store_id=? AND status<>'CLOSED'",owner,product,store);if(!existing.isEmpty())return Map.of("enquiry",dto(existing.getFirst(),false,true,null),"created",false);
        p=jdbc.queryForMap("SELECT p.*,s.name AS store_name,s.status AS store_status FROM vw_product p JOIN vw_store s ON s.id=p.store_id WHERE p.id=?",product);
        if(!text(p,"status").equals("PUBLISHED")||!text(p,"availability").equals("AVAILABLE")||!text(p,"store_status").equals("ACTIVE"))throw new ApiProblem(409,"PRODUCT_UNAVAILABLE","This product is currently unavailable for a new callback request");
        var snapshot=Map.of("id",product,"title",p.get("title"),"sku",p.get("sku"),"storeId",store,"storeName",p.get("store_name"),"price",((BigDecimal)p.get("price")).toPlainString(),"currency","INR");UUID enquiry=UUID.randomUUID();
        jdbc.update("INSERT INTO vw_enquiry(id,customer_id,store_id,product_id,product_snapshot,contact_name,contact_phone,consent_version,contact_retention_days) VALUES(?,?,?,?,?::jsonb,?,?,?,?)",enquiry,owner,store,product,json.toJson(snapshot),actor.name(),actor.identifier(),consentVersion(),retentionDays);var created=row(enquiry,store,false);event(created,owner,"CREATED","PUBLIC",note.isBlank()?null:note,null,"NEW",null,null,null);return Map.of("enquiry",dto(created,false,true,null),"created",true);
    }
    private int page(int value){return Math.min(1_000_000,Math.max(0,value));}
    private int size(int value){return Math.min(100,Math.max(1,value));}
    private String validStatus(String status){if(status!=null&&!status.isBlank()&&!STATUSES.contains(status))throw ApiProblem.bad("Invalid enquiry status");return status==null?"":status;}
    public Map<String,Object> customerList(String status,int page,int size){UUID owner=customer().id();String filter=validStatus(status);String where=" WHERE customer_id=?"+(filter.isBlank()?"":" AND status=?");List<Object> args=new ArrayList<>();args.add(owner);if(!filter.isBlank())args.add(filter);int total=jdbc.queryForObject("SELECT count(*) FROM vw_enquiry"+where,Integer.class,args.toArray());args.add(size(size));args.add(page(page)*size(size));var items=jdbc.queryForList("SELECT * FROM vw_enquiry"+where+" ORDER BY updated_at DESC,id LIMIT ? OFFSET ?",args.toArray()).stream().map(r->dto(r,false,false,null)).toList();return Map.of("items",items,"page",page(page),"size",size(size),"total",total);}
    public Map<String,Object> customerDetail(UUID enquiry){try{UUID owner=customer().id();var value=row(enquiry,null,false);if(!owner.equals(id(value,"customer_id")))throw ApiProblem.missing();return dto(value,false,true,null);}catch(ApiProblem denied){if(denied.status==401||denied.status==403)throw ApiProblem.missing();throw denied;}}
    public Map<String,Object> counts(UUID store){staff(store,false);return Map.of("unassignedNew",jdbc.queryForObject("SELECT count(*) FROM vw_enquiry WHERE store_id=? AND status='NEW' AND assignee_id IS NULL",Integer.class,store),"active",jdbc.queryForObject("SELECT count(*) FROM vw_enquiry WHERE store_id=? AND status<>'CLOSED'",Integer.class,store));}
    public Map<String,Object> staffDetail(UUID store,UUID enquiry){var actor=staff(store,false);return dto(row(enquiry,store,false),true,true,actor);}
    public Map<String,Object> staffList(UUID store,String status,String assignee,String query,int page,int size,boolean contactSearch){
        var actor=staff(store,false);String state=validStatus(status);StringBuilder where=new StringBuilder(" WHERE store_id=?");List<Object> args=new ArrayList<>();args.add(store);
        if(!state.isBlank()){where.append(" AND status=?");args.add(state);}if(assignee!=null&&!assignee.isBlank()){if(assignee.equals("unassigned"))where.append(" AND assignee_id IS NULL");else{where.append(" AND assignee_id=?");args.add(Inputs.id(assignee));}}
        if(query!=null&&!query.isBlank()){if(query.length()>200)throw ApiProblem.bad("Search is too long");String q="%"+query.trim().replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";where.append(" AND ((product_snapshot->>'title') ILIKE ? OR (product_snapshot->>'sku') ILIKE ?");args.add(q);args.add(q);if(contactSearch){where.append(" OR contact_name ILIKE ? OR COALESCE(contact_phone,'') ILIKE ?");args.add(q);args.add(q);}where.append(")");}
        int total=jdbc.queryForObject("SELECT count(*) FROM vw_enquiry"+where,Integer.class,args.toArray());args.add(size(size));args.add(page(page)*size(size));var items=jdbc.queryForList("SELECT * FROM vw_enquiry"+where+" ORDER BY updated_at DESC,id LIMIT ? OFFSET ?",args.toArray()).stream().map(r->dto(r,true,false,actor)).toList();return Map.of("items",items,"page",page(page),"size",size(size),"total",total);
    }
    private Map<String,Object> person(UUID user){if(user==null)return null;var values=jdbc.queryForList("SELECT id,name FROM vw_account WHERE id=?",user);return values.isEmpty()?Map.of("id",user,"name","Former user"):Map.of("id",user,"name",values.getFirst().get("name"));}
    private Map<String,Object> dto(Map<String,Object> row,boolean staff,boolean details,IdentityService.Account actor){
        var out=new LinkedHashMap<String,Object>();out.put("id",row.get("id"));out.put("product",json.fromJson(row.get("product_snapshot").toString(),new TypeToken<Map<String,Object>>(){}.getType()));var contact=new LinkedHashMap<String,Object>();contact.put("name",row.get("contact_name"));contact.put("phone",row.get("contact_phone"));contact.put("phoneVerified",false);contact.put("state",row.get("contact_state"));out.put("contact",contact);out.put("status",row.get("status"));out.put("outcome",row.get("outcome"));out.put("createdAt",timestamp(row,"created_at"));out.put("updatedAt",timestamp(row,"updated_at"));out.put("closedAt",timestamp(row,"closed_at"));out.put("contactRemovedAt",timestamp(row,"contact_redacted_at"));out.put("canReply",!text(row,"status").equals("CLOSED")&&available(row));
        if(staff){out.put("assignee",person(id(row,"assignee_id")));out.put("canClaim",text(row,"status").equals("NEW")&&eligible(actor.id(),id(row,"store_id")));out.put("canAssign",!text(row,"status").equals("CLOSED"));out.put("canChangeStatus",!Set.of("NEW","CLOSED").contains(text(row,"status")));out.put("canReopen",text(row,"status").equals("CLOSED")&&available(row));out.put("canAddNote",available(row));}
        if(details)out.put("events",events(row,staff));return out;
    }
    private List<Map<String,Object>> events(Map<String,Object> enquiry,boolean staff){
        String filter=staff?"":" AND e.visibility='PUBLIC' AND e.event_type IN('CREATED','STATUS_CHANGED','REOPENED','MESSAGE','CONTACT_REDACTED')";
        return jdbc.queryForList("SELECT e.*,a.name AS actor_name,a.kind AS actor_kind FROM vw_enquiry_event e LEFT JOIN vw_account a ON a.id=e.actor_id WHERE e.enquiry_id=?"+filter+" ORDER BY e.id",enquiry.get("id")).stream().map(e->{
            var out=new LinkedHashMap<String,Object>();out.put("id",e.get("id"));out.put("type",e.get("event_type"));String kind=e.get("actor_id")==null?"SYSTEM":text(e,"actor_kind");String name=kind.equals("CUSTOMER")?(staff?(available(enquiry)?text(e,"actor_name"):"Customer"):"You"):kind.equals("WORKFORCE")?(staff?text(e,"actor_name"):"Store team"):"System";var actor=new LinkedHashMap<String,Object>();actor.put("name",name);actor.put("kind",kind);if(staff)actor.put("id",e.get("actor_id"));out.put("actor",actor);out.put("text",e.get("body"));out.put("redacted",e.get("redacted"));out.put("createdAt",timestamp(e,"created_at"));out.put("fromStatus",e.get("from_status"));out.put("toStatus",e.get("to_status"));out.put("outcome",e.get("outcome"));if(staff){out.put("visibility",e.get("visibility"));out.put("fromAssignee",person(id(e,"from_assignee_id")));out.put("toAssignee",person(id(e,"to_assignee_id")));}return(Map<String,Object>)out;
        }).toList();
    }
    @Transactional public Map<String,Object> claim(UUID store,UUID enquiry){var scope=lockedStaff(store,enquiry);var row=scope.enquiry();requireActive(row);if(scope.actor().id().equals(id(row,"assignee_id")))return dto(row,true,true,scope.actor());if(row.get("assignee_id")!=null)throw new ApiProblem(409,"ENQUIRY_ALREADY_CLAIMED","Another teammate has claimed this enquiry; refresh to see its assignee");if(!eligible(scope.actor().id(),store))throw new ApiProblem(409,"CLAIM_MEMBERSHIP_REQUIRED","An accepted store membership is required to claim; assign an eligible teammate instead");jdbc.update("UPDATE vw_enquiry SET assignee_id=?,status='OPEN',updated_at=CURRENT_TIMESTAMP WHERE id=?",scope.actor().id(),enquiry);event(row,scope.actor().id(),"CLAIMED","INTERNAL",null,text(row,"status"),"OPEN",null,scope.actor().id(),null);return dto(row(enquiry,store,false),true,true,scope.actor());}
    @Transactional public Map<String,Object> assign(UUID store,UUID enquiry,Map<String,Object> body){var scope=lockedStaff(store,enquiry);var row=scope.enquiry();requireActive(row);UUID target=Inputs.id(Inputs.text(body,"assigneeId",40));requireEligible(target,store);String reason=Inputs.optional(body,"reason",1000);if(!reason.isBlank())requireText(row);if(target.equals(id(row,"assignee_id")))return dto(row,true,true,scope.actor());String state=text(row,"status").equals("NEW")?"OPEN":text(row,"status");jdbc.update("UPDATE vw_enquiry SET assignee_id=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",target,state,enquiry);event(row,scope.actor().id(),"ASSIGNED","INTERNAL",reason.isBlank()?null:reason,text(row,"status"),state,id(row,"assignee_id"),target,null);return dto(row(enquiry,store,false),true,true,scope.actor());}
    @Transactional public Map<String,Object> status(UUID store,UUID enquiry,Map<String,Object> body){var scope=lockedStaff(store,enquiry);var row=scope.enquiry();String next=validStatus(Inputs.text(body,"status",40)),before=text(row,"status");if(next.equals(before))return dto(row,true,true,scope.actor());if(!TRANSITIONS.getOrDefault(before,Set.of()).contains(next))throw new ApiProblem(409,"INVALID_TRANSITION","Claim, assign or reopen the enquiry before this status change");String reason=Inputs.optional(body,"reason",2000);if(!reason.isBlank())requireText(row);String outcome=next.equals("CLOSED")?Inputs.text(body,"outcome",30):null;if(outcome!=null&&!OUTCOMES.contains(outcome))throw ApiProblem.bad("Select a supported closure outcome");jdbc.update("UPDATE vw_enquiry SET status=?,outcome=?,closed_at=CASE WHEN ?='CLOSED' THEN CURRENT_TIMESTAMP ELSE NULL END,updated_at=CURRENT_TIMESTAMP WHERE id=?",next,outcome,next,enquiry);event(row,scope.actor().id(),"STATUS_CHANGED","PUBLIC",reason.isBlank()?null:reason,before,next,null,null,outcome);return dto(row(enquiry,store,false),true,true,scope.actor());}
    @Transactional public Map<String,Object> reopen(UUID store,UUID enquiry,Map<String,Object> body){var scope=lockedStaff(store,enquiry);var row=scope.enquiry();requireText(row);if(!text(row,"status").equals("CLOSED"))throw new ApiProblem(409,"ENQUIRY_NOT_CLOSED","Only a closed enquiry can be reopened");UUID target=Inputs.id(Inputs.text(body,"assigneeId",40));requireEligible(target,store);String reason=Inputs.text(body,"reason",2000);if(jdbc.queryForObject("SELECT count(*) FROM vw_enquiry WHERE customer_id=? AND product_id=? AND store_id=? AND status<>'CLOSED'",Integer.class,row.get("customer_id"),row.get("product_id"),store)>0)throw new ApiProblem(409,"ACTIVE_ENQUIRY_EXISTS","A newer active enquiry already exists for this product");jdbc.update("UPDATE vw_enquiry SET status='OPEN',assignee_id=?,outcome=NULL,closed_at=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?",target,enquiry);event(row,scope.actor().id(),"REOPENED","PUBLIC",reason,"CLOSED","OPEN",null,null,null);event(row,scope.actor().id(),"ASSIGNED","INTERNAL",null,"CLOSED","OPEN",id(row,"assignee_id"),target,null);return dto(row(enquiry,store,false),true,true,scope.actor());}
    @Transactional public Map<String,Object> customerMessage(UUID enquiry,Map<String,Object> body){var row=lockedCustomer(enquiry);requireText(row);requireActive(row);String message=Inputs.text(body,"text",4000);UUID actor=customer().id();event(row,actor,"MESSAGE","PUBLIC",message,null,null,null,null,null);if(text(row,"status").equals("AWAITING_CUSTOMER_RESPONSE")){jdbc.update("UPDATE vw_enquiry SET status='CUSTOMER_REPLIED' WHERE id=?",enquiry);event(row,actor,"STATUS_CHANGED","PUBLIC",null,"AWAITING_CUSTOMER_RESPONSE","CUSTOMER_REPLIED",null,null,null);}touch(enquiry);return dto(row(enquiry,id(row,"store_id"),false),false,true,null);}
    @Transactional public Map<String,Object> staffMessage(UUID store,UUID enquiry,Map<String,Object> body,boolean internal){var scope=lockedStaff(store,enquiry);var row=scope.enquiry();requireText(row);if(!internal)requireActive(row);event(row,scope.actor().id(),internal?"NOTE":"MESSAGE",internal?"INTERNAL":"PUBLIC",Inputs.text(body,"text",4000),null,null,null,null,null);touch(enquiry);return dto(row(enquiry,store,false),true,true,scope.actor());}
    private void unassign(UUID store,UUID account,UUID actor){identity.lockAdministration();identity.lockStore(store);if(eligible(account,store))return;for(var row:jdbc.queryForList("SELECT * FROM vw_enquiry WHERE store_id=? AND assignee_id=? AND status<>'CLOSED' ORDER BY id FOR UPDATE",store,account)){jdbc.update("UPDATE vw_enquiry SET status='NEW',assignee_id=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?",row.get("id"));event(row,actor,"UNASSIGNED","INTERNAL",null,text(row,"status"),"NEW",account,null,null);}}
    @EventListener @Transactional public void revoked(IdentityService.MembershipRevoked event){unassign(event.storeId(),event.accountId(),event.actorId());}
    @EventListener @Transactional public void workforceChanged(IdentityService.WorkforceAccessChanged event){identity.lockAdministration();for(UUID store:jdbc.queryForList("SELECT DISTINCT store_id FROM vw_enquiry WHERE assignee_id=? AND status<>'CLOSED' ORDER BY store_id",UUID.class,event.accountId()))unassign(store,event.accountId(),event.actorId());}
    private void redact(Map<String,Object> row,String state){if(!available(row))return;jdbc.update("UPDATE vw_enquiry SET contact_name=?,contact_phone=NULL,contact_state=?,contact_redacted_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?",state.equals("REMOVED_ACCOUNT")?"Deleted customer":"Contact removed",state,row.get("id"));jdbc.update("UPDATE vw_enquiry_event SET redacted=redacted OR body IS NOT NULL,body=NULL WHERE enquiry_id=?",row.get("id"));event(row,null,"CONTACT_REDACTED","PUBLIC",null,null,null,null,null,null);}
    @EventListener @Transactional public void deletedAccount(IdentityService.AccountDeleted event){identity.lockAdministration();for(UUID store:jdbc.queryForList("SELECT DISTINCT store_id FROM vw_enquiry WHERE customer_id=? ORDER BY store_id",UUID.class,event.accountId())){identity.lockStore(store);for(var row:jdbc.queryForList("SELECT * FROM vw_enquiry WHERE customer_id=? AND store_id=? ORDER BY id FOR UPDATE",event.accountId(),store))redact(row,"REMOVED_ACCOUNT");}}
    public List<UUID> retentionCandidates(){return jdbc.queryForList("SELECT id FROM vw_enquiry WHERE status='CLOSED' AND contact_state='AVAILABLE' AND closed_at<=CURRENT_TIMESTAMP-(LEAST(contact_retention_days,?)*INTERVAL '1 day') ORDER BY closed_at,id LIMIT 100",UUID.class,retentionDays);}
    @Transactional public boolean expireContact(UUID enquiry){var initial=row(enquiry,null,false);identity.lockAdministration();identity.lockStore(id(initial,"store_id"));var row=row(enquiry,id(initial,"store_id"),true);if(!text(row,"status").equals("CLOSED")||!available(row)||jdbc.queryForObject("SELECT count(*) FROM vw_enquiry WHERE id=? AND closed_at<=CURRENT_TIMESTAMP-(LEAST(contact_retention_days,?)*INTERVAL '1 day')",Integer.class,enquiry,retentionDays)==0)return false;redact(row,"EXPIRED");return true;}
}
